pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint256).max);

        // Configure the log contract with an always-reverting log BEFORE initialization.
        RevertingLog log = new RevertingLog();
        c.SetLogFile(address(log));
        c.Initialized();

        // Any Put by any actor with any amount must revert because LogFile.AddMessage reverts.
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(0) { ok = true; } catch { ok = false; }

        assertTrue(ok == false);
    }
}

contract RevertingLog {
    function AddMessage(address, uint, string calldata) external pure {
        revert();
    }
}

