pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface ILogSetter { function SetLogFile(address) external; }

contract InvMutTest is Test {
    C c;
    RevertingLog log;
    function setUp() public {
        c = new C();
        log = new RevertingLog();
    }
    function testFuzz_property(address actor, uint256 amount, uint256 lockTime) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1e24);
        // configure the log before initialization: in P this address is stored,
        // in M it is not (stays address(0))
        c.SetLogFile(address(log));
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(lockTime) { ok = true; } catch { ok = false; }
        // Rule: with a reverting log configured, every Put must revert.
        assertTrue(!ok, "Put must revert when the configured log reverts");
    }
}

contract RevertingLog {
    function AddMessage(address, uint256, string calldata) external pure {
        revert();
    }
}

