pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1e30);

        // adversarial log that reverts on any message
        RevertingLogFile rl = new RevertingLogFile();

        // configure the log before initialization (admissible domain)
        c.SetLogFile(address(rl));

        // deposit via the actor; Put must log through the reverting log -> revert
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: with a configured log that reverts, Put must revert for every
        // admissible (actor, amount). The mutant never stores the log, so its
        // AddMessage goes to address(0) and Put succeeds.
        assertTrue(!ok);
    }
}

contract RevertingLogFile {
    fallback() external payable {
        revert();
    }
}

