pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    FakeLog fl;

    function setUp() public {
        c = new C();
        fl = new FakeLog();
        c.SetLogFile(address(fl));
        c.Initialized();
    }

    function testFuzz_property(address actor, uint256 amount, uint256 lockTime, uint256 minSum) public {
        vm.assume(actor != address(c) && actor != address(this));
        amount = bound(amount, 1, 1e30);
        lockTime = bound(lockTime, 0, 1e12);
        minSum = bound(minSum, 0, amount);
        c.SetMinSum(minSum);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(lockTime);

        vm.warp(block.timestamp + lockTime + 1);
        vm.prank(actor);
        bool ok;
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "a recorded deposit must be collectable after its unlock time");
    }
}

contract FakeLog {
    function AddMessage(address, uint256, string calldata) external pure {}
}

