    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 lockTime, uint256 amount, address actor) public {
        vm.assume(lockTime > 0);
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(amount <= actor.balance + 1e30);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(lockTime);
        (uint256 unlockTime, ) = c.Acc(actor);
        assertTrue(unlockTime > block.timestamp);
    }
}

